import * as rt from '@midnight-ntwrk/compact-runtime';
import { Contract, ledger, pureCircuits } from './c/contract/index.js';
const sks = { a: new Uint8Array(32).fill(1), b: new Uint8Array(32).fill(2) };
const pk = k => pureCircuits.publicKey(sks[k]);
const c = new Contract({ secretKey: (ctx) => [ctx.privateState, ctx.privateState.sk] });
const addr = rt.sampleContractAddress();
let ps = { sk: sks.a };
const cc = rt.createConstructorContext(ps, '0'.repeat(64));
const init = c.initialState(cc);
let ctx = rt.createCircuitContext(addr, init.currentZswapLocalState.coinPublicKey ?? '0'.repeat(64), init.currentContractState, init.currentPrivateState);
const as = (k) => { ctx = { ...ctx, currentPrivateState: { sk: sks[k] } }; };
const show = (l) => { const s = ledger(ctx.currentQueryContext.state); console.log(l, 'supply', s.totalSupply, [...s.balances].map(([k,v])=>[Buffer.from(k).toString('hex').slice(0,6),v])); };
const run = async (l, k, f) => { as(k); try { const r = await f(); ctx = r.context; console.log(l,'ok'); } catch(e){ console.log(l,'FAIL',e.message);} show(' '); };
show('init; admin==a?'+(Buffer.from(ledger(ctx.currentQueryContext.state).admin).equals(Buffer.from(pk('a')))));
await run('b mints', 'b', () => c.circuits.mint(ctx, pk('b'), 5n));
await run('a mints 100 to a', 'a', () => c.circuits.mint(ctx, pk('a'), 100n));
await run('a->b 30', 'a', () => c.circuits.transfer(ctx, pk('b'), 30n));
await run('b->a 31 (too much)', 'b', () => c.circuits.transfer(ctx, pk('a'), 31n));
await run('b burn 10', 'b', () => c.circuits.burn(ctx, 10n));
await run('b burn 21 (too much)', 'b', () => c.circuits.burn(ctx, 21n));
await run('a self-transfer 70', 'a', () => c.circuits.transfer(ctx, pk('a'), 70n));
as('a'); const r = await c.circuits.balanceOf(ctx, pk('b')); console.log('balanceOf b', r.result, 'unknown', (await c.circuits.balanceOf(ctx, new Uint8Array(32).fill(9))).result);
EOF
